A linked list is a chain of structs where each node holds a value and a pointer to the next node. The last node points to `NULL`.

```c
#include <stdio.h>
#include <stdlib.h>

struct node {
    int value;
    struct node *next;
};

/* Returns 0 on success, -1 if malloc fails. */
int push_front(struct node **head, int value) {
    struct node *n = malloc(sizeof *n);
    if (n == NULL) {
        return -1;
    }
    n->value = value;
    n->next = *head;
    *head = n;
    return 0;
}

void print_list(const struct node *head) {
    for (const struct node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d -> ", cur->value);
    }
    printf("NULL\n");
}

void free_list(struct node *head) {
    while (head != NULL) {
        struct node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct node *head = NULL;
    for (int i = 1; i <= 3; i++) {
        if (push_front(&head, i) != 0) {
            free_list(head);
            return 1;
        }
    }
    print_list(head);
    free_list(head);
    return 0;
}
```

Output: `3 -> 2 -> 1 -> NULL`

Key points:
- `push_front` takes `struct node **` (a pointer to the head pointer) so it can change `head` in `main`.
- In `free_list`, save `next` before `free`. Reading `head->next` after freeing is use-after-free.
- `->` is shorthand for `(*ptr).field`.

Read the file one character at a time with `fgetc` and track whether you are inside a word.

```c
#include <ctype.h>
#include <stdio.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 1;
    }
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror(argv[1]);
        return 1;
    }
    long lines = 0, words = 0, chars = 0;
    int in_word = 0;
    int c;
    while ((c = fgetc(fp)) != EOF) {
        chars++;
        if (c == '\n') {
            lines++;
        }
        if (isspace(c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }
    if (ferror(fp)) {
        perror("read");
        fclose(fp);
        return 1;
    }
    fclose(fp);
    printf("%ld %ld %ld %s\n", lines, words, chars, argv[1]);
    return 0;
}
```

Steps:
1. Compile: `gcc -std=c11 -Wall -o mywc mywc.c`
2. Run: `./mywc notes.txt`
3. Compare with `wc notes.txt`.

Key points:
- `c` must be `int`, not `char`. `EOF` is a negative value that does not fit safely in every `char`.
- `fgetc` returns `EOF` on both end-of-file and error; `ferror` tells them apart.
- `chars` counts bytes, which matches `wc -c`.

This uses POSIX sockets (Linux/macOS). A socket is a file descriptor (an integer handle) for a network connection. `getaddrinfo` turns a hostname and port into addresses.

```c
#define _POSIX_C_SOURCE 200112L
#include <netdb.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s HOST PORT\n", argv[0]);
        return 1;
    }
    struct addrinfo hints = {0}, *res, *rp;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    int rc = getaddrinfo(argv[1], argv[2], &hints, &res);
    if (rc != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rc));
        return 1;
    }
    int fd = -1;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (fd == -1) continue;
        if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    if (fd == -1) {
        fprintf(stderr, "could not connect\n");
        return 1;
    }
    const char *msg = "hello\n";
    if (send(fd, msg, strlen(msg), 0) == -1) {
        perror("send");
        close(fd);
        return 1;
    }
    char buf[512];
    ssize_t n;
    while ((n = recv(fd, buf, sizeof buf, 0)) > 0) {
        fwrite(buf, 1, (size_t)n, stdout);
    }
    if (n == -1) perror("recv");
    close(fd);
    return 0;
}
```

Test it:
1. Terminal 1: `nc -l 9000`
2. Terminal 2: `./client 127.0.0.1 9000`
3. Type a reply in terminal 1, then press Ctrl+C.

Key points:
- `recv` returns 0 when the other side closes the connection.
- `send` can send fewer bytes than asked; for large data, loop until all are sent.

My program segfaults. How do I find where using gdb?

```c
#include <stdio.h>

int main(void) {
    int *p = NULL;
    for (int i = 0; i < 3; i++) {
        p[i] = i;
    }
    printf("%d\n", p[0]);
    return 0;
}
```

A segfault (segmentation fault) means the program touched memory it is not allowed to access. Here `p` is `NULL`, so `p[i] = i` writes to address 0.

Find it with gdb (the GNU debugger):
1. Compile with debug info and no optimisation: `gcc -std=c11 -g -O0 -o prog prog.c`
2. Start gdb: `gdb ./prog`
3. Type `run`. gdb stops at the crash and shows the line `p[i] = i;`.
4. Type `bt` (backtrace) to see the chain of function calls that led there.
5. Type `print p` and `print i`. You will see `p = 0x0` and `i = 0`.
6. Type `quit`.

Fix: give `p` real memory.

```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *p = malloc(3 * sizeof *p);
    if (p == NULL) {
        perror("malloc");
        return 1;
    }
    for (int i = 0; i < 3; i++) {
        p[i] = i;
    }
    printf("%d\n", p[0]);
    free(p);
    return 0;
}
```

Key points:
- `-g` adds line numbers and variable names. Without it gdb shows only addresses.
- On macOS, gdb needs code signing; use `lldb` instead (`run`, `bt`, `p p`).
- `-fsanitize=address` also reports the exact line of a bad memory access.

Valgrind says "definitely lost: 40 bytes in 1 blocks". What does that mean and how do I fix it?

```c
#include <stdlib.h>

int main(void) {
    int *nums = malloc(10 * sizeof(int));
    if (nums == NULL) return 1;
    for (int i = 0; i < 10; i++) nums[i] = i;
    nums = NULL;
    return 0;
}
```

"Definitely lost" means a heap block was never freed and no pointer to it exists any more. That is a memory leak. `nums = NULL;` overwrites the only pointer to the 40-byte block (10 ints x 4 bytes), so it can never be freed.

Fix: call `free` before you drop the pointer.

```c
#include <stdlib.h>

int main(void) {
    int *nums = malloc(10 * sizeof *nums);
    if (nums == NULL) {
        return 1;
    }
    for (int i = 0; i < 10; i++) {
        nums[i] = i;
    }
    free(nums);
    nums = NULL;
    return 0;
}
```

Check it:
1. `gcc -std=c11 -g -o prog prog.c`
2. `valgrind --leak-check=full ./prog`
3. Look for `All heap blocks were freed -- no leaks are possible`.

Key points:
- Setting a pointer to `NULL` after `free` is good. Setting it before `free` leaks.

It means the program read 4 bytes (one `int` on most systems) from memory it does not own. Common causes:

1. Reading past the end of an array (out of bounds).
2. Reading memory after `free` (use-after-free).
3. Reading through an uninitialised pointer.

Example that triggers it:

```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *a = malloc(3 * sizeof *a);
    if (a == NULL) {
        return 1;
    }
    a[0] = 1; a[1] = 2; a[2] = 3;
    printf("%d\n", a[3]); /* bug: valid indexes are 0..2 */
    free(a);
    return 0;
}
```

How to read the report:
1. The first stack trace shows the line doing the bad read.
2. "Address ... is 0 bytes after a block of size 12 alloc'd" shows which allocation you overran.
3. Fix the index or loop bound, then rerun valgrind.

Key points:
- "Size 4" is the width of the access, not the array length.

Because signed integer overflow is undefined behaviour (UB). UB means the C standard places no requirements on what happens. The compiler may assume UB never occurs, so it reasons "`x + 1` can never be less than `x`" and deletes the check.

Check before doing the operation instead:

```c
#include <limits.h>
#include <stdio.h>

/* Returns 0 and stores the sum on success, -1 on overflow. */
int add_checked(int a, int b, int *out) {
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) {
        return -1;
    }
    *out = a + b;
    return 0;
}

int main(void) {
    int r;
    if (add_checked(INT_MAX, 1, &r) != 0) {
        printf("overflow detected\n");
    } else {
        printf("%d\n", r);
    }
    return 0;
}
```

Steps to catch UB at runtime:
1. Compile: `gcc -std=c11 -g -fsanitize=undefined prog.c -o prog`
2. Run `./prog`. The sanitizer prints `signed integer overflow` with the file and line.

Key points:
- Unsigned overflow is defined: it wraps around modulo 2^N.
- GCC and Clang provide `__builtin_add_overflow(a, b, &r)`; it is not standard C.
- Other common UB: out-of-bounds access, using freed memory, `i = i++;`.

Use bitwise operators on unsigned integers. A mask is a value with only the bits you care about set. `UINT32_C(1) << n` is a mask with only bit `n` set.

```c
#include <stdint.h>
#include <stdio.h>

uint32_t bit_set(uint32_t x, unsigned n)    { return x | (UINT32_C(1) << n); }
uint32_t bit_clear(uint32_t x, unsigned n)  { return x & ~(UINT32_C(1) << n); }
uint32_t bit_toggle(uint32_t x, unsigned n) { return x ^ (UINT32_C(1) << n); }
int bit_test(uint32_t x, unsigned n)        { return (int)((x >> n) & 1u); }

unsigned popcount(uint32_t x) {
    unsigned count = 0;
    while (x != 0) {
        x &= x - 1; /* clears the lowest set bit */
        count++;
    }
    return count;
}

int main(void) {
    uint32_t x = 0;
    x = bit_set(x, 3);    /* binary 1000 = 8 */
    x = bit_set(x, 0);    /* binary 1001 = 9 */
    x = bit_toggle(x, 3); /* binary 0001 = 1 */
    x = bit_clear(x, 0);  /* 0 */
    printf("x=%u test3=%d\n", (unsigned)x, bit_test(x, 3));
    printf("popcount(0xF0)=%u\n", popcount(0xF0));
    return 0;
}
```

Output:
```
x=0 test3=0
popcount(0xF0)=4
```

Key points:
- `n` must be 0..31 for a 32-bit value. Shifting by 32 or more is undefined behaviour.
- Use unsigned types. Shifting a 1 into the sign bit of a signed `int` is undefined behaviour.
- `x & (x - 1)` removes the lowest set bit; it is a common trick.

Why does this print 8 instead of 5, and the string doesn't reverse properly?

```c
void reverse(char *s) {
    size_t n = sizeof(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
    printf("%zu\n", n);
}
```

`s` is a `char *`, so `sizeof(s)` is the size of the pointer (8 bytes on 64-bit systems), not the length of the text. When you pass an array to a function it decays (converts) to a pointer, and the length is lost. Use `strlen`, which counts characters up to the `'\0'`.

With `n = 8` on a 5-character string, the loop also swapped bytes past the end of the string: out-of-bounds access.

Fixed version:

```c
#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

int main(void) {
    char word[] = "hello";
    reverse(word);
    printf("%s (%zu chars)\n", word, strlen(word));
    return 0;
}
```

Output: `olleh (5 chars)`

Key points:
- `sizeof` on an array in the same scope gives the array size (`sizeof word` is 6, including `'\0'`). On a pointer it gives the pointer size.
- Declare the string as `char word[]`, not `char *word = "hello"`. String literals are read-only; modifying one is undefined behaviour.
- An empty string gives `n = 0`, so the loop does nothing. That is safe.

Use `fwrite` to write raw bytes and `fread` to read them back. Open the file in binary mode (`"wb"`, `"rb"`).

```c
#include <stdio.h>

struct player {
    char name[16];
    int score;
};

int main(void) {
    struct player out[2] = {{"ana", 120}, {"bo", 95}};
    FILE *fp = fopen("players.bin", "wb");
    if (fp == NULL) {
        perror("fopen write");
        return 1;
    }
    size_t written = fwrite(out, sizeof out[0], 2, fp);
    if (fclose(fp) != 0 || written != 2) {
        fprintf(stderr, "write failed\n");
        return 1;
    }

    struct player in[2];
    fp = fopen("players.bin", "rb");
    if (fp == NULL) {
        perror("fopen read");
        return 1;
    }
    size_t got = fread(in, sizeof in[0], 2, fp);
    fclose(fp);
    if (got != 2) {
        fprintf(stderr, "read %zu of 2 records\n", got);
        return 1;
    }
    for (size_t i = 0; i < got; i++) {
        printf("%s %d\n", in[i].name, in[i].score);
    }
    return 0;
}
```

Steps:
1. Compile: `gcc -std=c11 -Wall -o players players.c`
2. Run `./players`. It prints `ana 120` and `bo 95`.
3. Inspect the file: `xxd players.bin`.

Key points:
- `fwrite`/`fread` return the number of items (records), not bytes. Compare it to what you asked for.
- `fclose` can fail while flushing buffered data, so check it after writing.
- This format is not portable: padding (unused bytes the compiler adds between fields) and endianness (byte order) can differ between machines.
